-- NEXTPATH initial schema. Apply through Supabase CLI/SQL editor as the service role.
create extension if not exists pgcrypto;
create type public.user_role as enum ('student','admin');
create type public.application_status as enum ('DISCOVERED','SAVED','PREPARING','READY','SUBMITTED','ACCEPTED','REJECTED','EXPIRED');
create table public.users (id uuid primary key references auth.users(id) on delete cascade, email text not null unique, role public.user_role not null default 'student', created_at timestamptz not null default now());
create table public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.users(id) on delete cascade, full_name text, date_of_birth date, nationality text, residency_country text, phone text, bio text, career_goals text[] not null default '{}', gpa numeric, gpa_scale numeric, education_level text, academic_year int, profile_completeness int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((gpa is null) = (gpa_scale is null)));
create table public.educations (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, institution text not null, degree text not null, field_of_study text, start_date date, end_date date, is_current boolean not null default false, gpa numeric, gpa_scale numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.skills (id uuid primary key default gen_random_uuid(), name text not null unique, category text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.languages (id uuid primary key default gen_random_uuid(), name text not null unique, iso_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profile_skills (profile_id uuid references public.profiles(id) on delete cascade, skill_id uuid references public.skills(id) on delete restrict, proficiency text, primary key(profile_id,skill_id));
create table public.profile_languages (profile_id uuid references public.profiles(id) on delete cascade, language_id uuid references public.languages(id) on delete restrict, proficiency text, primary key(profile_id,language_id));
create table public.experiences (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, organization text, description text, start_date date, end_date date, is_current boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, type text not null, file_path text not null unique, file_name text not null, mime_type text not null, uploaded_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, website text, description text, country text, verified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunities (id uuid primary key default gen_random_uuid(), title text not null, type text not null, organization_id uuid not null references public.organizations(id) on delete restrict, description text not null, category text, field text, website text, application_url text, funding_category text not null default 'UNKNOWN', covers_tuition boolean, covers_accommodation boolean, covers_flights boolean, covers_visa boolean, covers_meals boolean, covers_insurance boolean, stipend_amount numeric, stipend_currency text, location_type text not null, country text, city text, region text, start_date date, end_date date, deadline date not null, source_url text not null, last_verified_at timestamptz, verification_status text not null default 'PENDING_REVIEW', required_documents text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunity_requirements (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null unique references public.opportunities(id) on delete cascade, nationality_allowlist text[], age_min int, age_max int, education_level_required text, academic_year_min int, gpa_min numeric, gpa_min_scale numeric, residency_allowlist text[], required_degree text, legal_requirement_description text, legal_requirement_structured_check boolean, relevant_majors text[], relevant_skills text[], relevant_interests text[], min_experience_years int, experience_description text, career_goal_tags text[], preferred_languages jsonb, relevant_projects_hint text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunity_sources (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, source_url text not null, retrieved_at timestamptz not null default now(), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.saved_opportunities (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, opportunity_id uuid not null references public.opportunities(id) on delete cascade, saved_at timestamptz not null default now(), unique(profile_id,opportunity_id));
create table public.applications (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, opportunity_id uuid not null references public.opportunities(id) on delete restrict, status public.application_status not null default 'DISCOVERED', notes text, applied_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(profile_id,opportunity_id));
create table public.application_fields (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, field_key text not null, value jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(application_id,field_key));
create table public.application_documents (application_id uuid references public.applications(id) on delete cascade, document_id uuid references public.documents(id) on delete restrict, created_at timestamptz not null default now(), primary key(application_id,document_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, body text, data jsonb not null default '{}', read_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recommendations (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, opportunity_id uuid not null references public.opportunities(id) on delete cascade, score numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(profile_id,opportunity_id));
create index opportunities_deadline_idx on public.opportunities(deadline); create index opportunities_filters_idx on public.opportunities(type, funding_category, location_type);
-- RLS: ownership derives from profiles; lookup/opportunity data is public read-only.
alter table public.profiles, public.educations, public.profile_skills, public.profile_languages, public.experiences, public.documents, public.saved_opportunities, public.applications, public.application_fields, public.application_documents, public.notifications, public.recommendations enable row level security;
create policy "profile owner" on public.profiles for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "education owner" on public.educations for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "experience owner" on public.experiences for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "document owner" on public.documents for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "saved owner" on public.saved_opportunities for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "application owner" on public.applications for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "notification owner" on public.notifications for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
create policy "recommendation owner" on public.recommendations for all using (profile_id in (select id from public.profiles where user_id=auth.uid())) with check (profile_id in (select id from public.profiles where user_id=auth.uid()));
alter table public.opportunities, public.organizations, public.opportunity_requirements, public.opportunity_sources enable row level security;
create policy "public opportunity read" on public.opportunities for select using (true); create policy "public org read" on public.organizations for select using (true); create policy "public requirements read" on public.opportunity_requirements for select using (true); create policy "public sources read" on public.opportunity_sources for select using (true);
